async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder();
  let state = initial;
  let pending = "";
  let scanIndex = 0;
  let physicalLine = 1;
  let recordIndex = 0;
  let closed = false;

  async function closeIterator() {
    if (closed) return;
    closed = true;

    try {
      if (typeof iterator.return === "function") {
        await iterator.return();
      }
    } catch {
      // Cleanup failures are intentionally ignored.
    }
  }

  async function processLine(line) {
    if (line.trim().length === 0) return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex,
    });

    state = result.state;
    recordIndex += 1;
    return result.done === true;
  }

  async function appendAndProcess(text) {
    pending += text;

    for (;;) {
      const newlineIndex = pending.indexOf("\n", scanIndex);

      if (newlineIndex === -1) {
        scanIndex = pending.length;
        return false;
      }

      const line = pending.slice(0, newlineIndex);
      pending = pending.slice(newlineIndex + 1);
      scanIndex = 0;

      if (await processLine(line)) return true;
      physicalLine += 1;
    }
  }

  try {
    for (;;) {
      const next = await iterator.next();

      if (next.done) break;

      if (await appendAndProcess(decoder.decode(next.value, { stream: true }))) {
        await closeIterator();
        return state;
      }
    }

    if (await appendAndProcess(decoder.decode())) {
      await closeIterator();
      return state;
    }

    if (pending.length > 0 && (await processLine(pending))) {
      await closeIterator();
      return state;
    }

    return state;
  } catch (error) {
    await closeIterator();
    throw error;
  }
}
